<script setup lang="ts">
import { onMounted, ref } from "vue"; import { api } from "../api";
const backups=ref<any[]>([]), logs=ref<any[]>([]), message=ref(""), error=ref("");
async function load(){try{[backups.value,logs.value]=await Promise.all([api<any[]>("/backups"),api<any[]>("/data-update")]);}catch(e:any){error.value=e.message;}} async function backup(){try{const b=await api<any>("/backups",{method:"POST"});message.value=`已创建备份：${b.path}`;await load();}catch(e:any){error.value=e.message;}} async function restore(item:any){if(!confirm(`恢复 ${item.name} 会将当前本地数据替换为该备份；系统会先自动创建安全备份。继续吗？`))return;try{const r=await api<any>(`/backups/${item.name}/restore?confirmed=true`,{method:"POST"});message.value=`已恢复 ${r.restored}；恢复前安全备份：${r.safety_backup}`;await load();}catch(e:any){error.value=e.message;}} function exportAll(){window.location.href="/api/exports/all";} async function importAll(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;if(!confirm("导入会恢复压缩包中的本地数据，并先自动创建安全备份。继续吗？"))return;try{const r=await api<any>("/imports/all?confirmed=true",{method:"POST",body:await file.arrayBuffer(),headers:{"Content-Type":"application/zip"}});message.value=`导入并恢复成功；安全备份：${r.safety_backup}`;await load();}catch(e:any){error.value=e.message;}}
onMounted(load);
</script>
<template><section class="panel"><div class="panel-head"><div><h2>数据金库</h2><p class="muted">核心数据固定保存在项目内的 <b>data/investment_lab.db</b>。备份包含 SQLite、config、reports 和导入 CSV；复制整个项目即可迁移。</p></div><div class="toolbar"><button class="button" @click="backup">立即备份</button><button class="button ghost" @click="exportAll">导出全部数据</button><label class="file">导入全部数据 <input type="file" accept=".zip,application/zip" @change="importAll"/></label></div></div><div v-if="message" class="status">{{message}}</div><div v-if="error" class="status error">{{error}}</div><div v-if="!backups.length" class="empty">暂时没有备份。建议首次录入数据后立即创建一份。</div><div v-else class="table-wrap"><table class="data-table"><thead><tr><th>备份</th><th>创建时间</th><th>含数据库</th><th>相对路径</th><th></th></tr></thead><tbody><tr v-for="item in backups"><td>{{item.name}}</td><td>{{item.created_at}}</td><td>{{item.has_database?'是':'否'}}</td><td>{{item.path}}</td><td><button class="button ghost" @click="restore(item)">恢复此备份</button></td></tr></tbody></table></div></section><section class="panel section-gap"><div class="panel-head"><div><h3>数据更新日志</h3><p class="muted">行情更新失败不会清空缓存；每次写入和回退都留存于本地审计日志。</p></div></div><div v-if="!logs.length" class="empty">暂无更新日志。</div><div v-else class="table-wrap"><table class="data-table"><thead><tr><th>开始</th><th>来源</th><th>状态</th><th>写入行数</th><th>说明</th></tr></thead><tbody><tr v-for="log in logs"><td>{{log.started_at}}</td><td>{{log.source}}</td><td><span class="tag">{{log.status}}</span></td><td>{{log.records_written}}</td><td>{{log.message ?? "—"}}</td></tr></tbody></table></div></section></template>
